read_only_graph_and_bundle_reproduction.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {build} from 'esbuild';
const sha = v => createHash('sha256').update(v).digest('hex');
const inputs=JSON.parse(fs.readFileSync('docs/remediation/evidence/W04.02/source-inputs-v1.json','utf8'));
const graph=await build(inputs.graph.options);
const actual=Object.keys(graph.metafile.inputs).filter(p=>fs.existsSync(p)).sort().map(p=>({path:p,sha256:sha(fs.readFileSync(p))}));
const expected=[...inputs.graph.files].sort((a,b)=>a.path.localeCompare(b.path));
const got=[...actual].sort((a,b)=>a.path.localeCompare(b.path));
const graphSame=JSON.stringify(got)===JSON.stringify(expected);
const version=fs.readFileSync('src/sdk/version.ts','utf8').match(/'([^']+)'/)[1];
const banner=`/* edge-personalization SDK v${version} — one package: core (identity, transport), emit (four capture paths), listen (decisions). */`;
const common={bundle:true,platform:'browser',target:'es2022',minify:false,sourcemap:false,legalComments:'none',logLevel:'info',metafile:true,banner:{js:banner},write:false};
const bundles=[];
for(const [entry,outfile,format] of [['src/sdk/index.ts','public/sdk/edge-personalization.esm.js','esm'],['src/sdk/browser.ts','public/sdk/edge-personalization.js','iife']]){
const b=await build({...common,entryPoints:[path.resolve(entry)],outfile:path.resolve(outfile),format});
const bytes=b.outputFiles[0].contents, stored=fs.readFileSync(outfile);
bundles.push({path:outfile,bytes:bytes.length,sha256:sha(bytes),storedSha256:sha(stored),equal:Buffer.from(bytes).equals(stored),localInputs:Object.keys(b.metafile.inputs).sort()});
}
console.log(JSON.stringify({at:new Date().toISOString(),graphInputs:got.length,expectedInputs:expected.length,graphSame,missing:expected.filter(f=>!got.some(g=>g.path===f.path)),unexpected:got.filter(f=>!expected.some(g=>g.path===f.path)),bundles},null,2));
if(!graphSame||bundles.some(b=>!b.equal))process.exit(1);
NODE

